import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        final String mapping = "11222333444555666777888999";  // value of 'a'..'z'
        int n = s.length(), offset = 8 * n;
        int[] freq = new int[16 * n + 1];
        long answer = 0;
        // A sum divisible by the length means an integer average k in 1..9:
        // shift every value by -k and count zero-sum substrings with prefix-sum frequencies.
        for (int average = 1; average <= 9; average++) {
            Arrays.fill(freq, 0);
            int prefix = offset;
            freq[prefix] = 1;
            for (int i = 0; i < n; i++) {
                prefix += mapping.charAt(s.charAt(i) - 'a') - '0' - average;
                answer += freq[prefix];
                freq[prefix]++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSpace(string(raw))
	const mapping = "11222333444555666777888999" // value of 'a'..'z'
	n := len(s)
	offset := 8 * n
	freq := make([]int32, 16*n+1)
	var answer int64
	// A sum divisible by the length means an integer average k in 1..9:
	// shift every value by -k and count zero-sum substrings with prefix-sum frequencies.
	for average := 1; average <= 9; average++ {
		clear(freq)
		prefix := offset
		freq[prefix] = 1
		for i := 0; i < n; i++ {
			prefix += int(mapping[s[i]-'a']-'0') - average
			answer += int64(freq[prefix])
			freq[prefix]++
		}
	}
	fmt.Println(answer)
}
